contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint balBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        require(amount <= balBefore);
        c.withdraw(amount); if (__ESBMC_reverted()) return;
        uint balAfter = address(c).balance;
        uint testBalAfter = address(this).balance;
        assert(balAfter == balBefore - amount && testBalAfter == testBalBefore + amount);
    }

    receive() external payable {}
}

