// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        uint balBefore = address(c).balance;
        uint testBalBefore = address(this).balance;
        vm.assume(amount <= balBefore);
        try c.withdraw(amount) {} catch { return; }
        uint balAfter = address(c).balance;
        uint testBalAfter = address(this).balance;
        assertTrue(balAfter == balBefore - amount && testBalAfter == testBalBefore + amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
